function median(array $arr): float {
    sort($arr);
    $n = count($arr);
    if ($n % 2 === 1) return $arr[$n >> 1];
    return ($arr[$n / 2 - 1] + $arr[$n / 2]) / 2.0;
}

function mean(array $arr): float {
    if (empty($arr)) return 0.0;
    return array_sum($arr) / count($arr);
}

function stddev(array $arr): float {
    $n = count($arr);
    if ($n <= 1) return 0.0;
    $mean = array_sum($arr) / $n;
    $var = 0.0;
    foreach ($arr as $v) { $d = $v - $mean; $var += $d * $d; }
    return sqrt($var / $n);
}

