function boyerMoore(string $text, string $pattern): int {
    $n = strlen($text);
    $m = strlen($pattern);
    if ($m === 0) return 0;
    $shift = array_fill(0, 256, $m);
    for ($i = 0; $i < $m - 1; $i++) $shift[ord($pattern[$i])] = $m - 1 - $i;
    $i = 0;
    while ($i <= $n - $m) {
        $j = $m - 1;
        while ($j >= 0 && $pattern[$j] === $text[$i + $j]) $j--;
        if ($j < 0) return $i;
        $i += $shift[ord($text[$i + $m - 1])];
    }
    return -1;
}

