class RingBuffer {
    private array $buf;
    private int $head = 0, $tail = 0, $size = 0, $cap;
    public function __construct(int $cap) { $this->cap = $cap; $this->buf = []; }
    public function push(mixed $v): void { $this->buf[$this->tail % $this->cap] = $v; $this->tail++; if ($this->size < $this->cap) $this->size++; else $this->head++; }
    public function pop(): mixed { if ($this->size === 0) return null; $v = $this->buf[$this->head % $this->cap]; $this->head++; $this->size--; return $v; }
    public function size(): int { return $this->size; }
}

function factorial(int $n): int {
    if ($n < 0) throw new \InvalidArgumentException('n must be non-negative');
    $r = 1;
    for ($i = 2; $i <= $n; $i++) $r *= $i;
    return $r;
}

function selectionSort(array &$arr): void {
    $n = count($arr);
    for ($i = 0; $i < $n - 1; $i++) {
        $min = $i;
        for ($j = $i + 1; $j < $n; $j++)
            if ($arr[$j] < $arr[$min]) $min = $j;
        [$arr[$i], $arr[$min]] = [$arr[$min], $arr[$i]];
    }
}

function insertionSort(array &$arr): void {
    $n = count($arr);
    for ($i = 1; $i < $n; $i++) {
        $key = $arr[$i];
        $j = $i - 1;
        while ($j >= 0 && $arr[$j] > $key) { $arr[$j + 1] = $arr[$j]; $j--; }
        $arr[$j + 1] = $key;
    }
}

