function sundayMatch(string $text, string $pattern): int {
    $n = strlen($text);
    $m = strlen($pattern);
    if ($m === 0) return 0;
    $shift = array_fill(0, 256, $m + 1);
    for ($i = 0; $i < $m; $i++) $shift[ord($pattern[$i])] = $m - $i;
    $i = 0;
    while ($i <= $n - $m) {
        $j = 0;
        while ($j < $m && $text[$i + $j] === $pattern[$j]) $j++;
        if ($j === $m) return $i;
        $i += ($i + $m < $n) ? $shift[ord($text[$i + $m])] : 1;
